import fs from "fs";

// The 19 snippets exactly as defined in src/cli/explore/static/app.js
const SNIPPETS = [
	{ id: "identity", group: "Basics", label: "Identity application", code: "(\\x -> x) 42" },
	{ id: "annotated", group: "Basics", label: "Annotated lambda", code: "\\(x: String) -> x" },
	{ id: "implicit", group: "Basics", label: "Implicit argument", code: '(\\x => \\(y: String) -> y) "hello"' },
	{ id: "bool", group: "Basics", label: "Boolean literal", code: "true" },
	{ id: "higher-order", group: "Functions", label: "Higher-order", code: "\\f -> \\x -> f (f x)" },
	{ id: "multi-param", group: "Functions", label: "Multi-param arrow", code: "(x: Num) -> (y: Num) -> Num" },
	{ id: "implicit-pi", group: "Functions", label: "Implicit Pi", code: "(x: Num) => Num" },
	{ id: "struct", group: "Row types", label: "Struct projection", code: "{ x: 1, y: 2 }.x" },
	{ id: "poly-proj", group: "Row types", label: "Polymorphic projection", code: "\\obj -> obj.x" },
	{ id: "sigma", group: "Row types", label: "Dependent struct", code: "{ x: 1, y: :x + 2 }" },
	{ id: "nested-sigma", group: "Row types", label: "Nested dependent", code: "{ point: { x: 1, y: 2 }, halved: { a: :point.x / 2, b: :point.y / 2 } }" },
	{ id: "row-poly", group: "Row types", label: "Row polymorphism", code: "\\(r: Row) -> { foo: Num | r }" },
	{ id: "tuple", group: "Row types", label: "Tuple", code: '{ 1, "hello", true }' },
	{ id: "variant-match", group: "Pattern matching", label: "Variant match", code: "\\x -> match x | #nil a -> 0 | #cons {el, rest} -> 1" },
	{ id: "struct-match", group: "Pattern matching", label: "Struct destructure", code: "match { x: 1 } | { x: a } -> a" },
	{ id: "nested-match", group: "Pattern matching", label: "Nested struct match", code: "\\x -> match x | { foo: { y: y }, bar: f } -> f y | { z: { w: w } } -> w" },
	{ id: "wildcard", group: "Pattern matching", label: "Wildcard + literal", code: "match 1 | 1 -> 2" },
	{ id: "block", group: "Blocks", label: "Let binding", code: "{ let id = \\x -> x; return id 42; }" },
	{ id: "block-proj", group: "Blocks", label: "Let + projection", code: "{ let proj = \\obj -> obj.x; }" },
];

const OUT = "/tmp/yap-explore-results";
fs.rmSync(OUT, { recursive: true, force: true });
fs.mkdirSync(OUT, { recursive: true });

const run = async (s) => {
	const res = await fetch("http://localhost:3333/run", {
		method: "POST",
		headers: { "Content-Type": "application/json" },
		body: JSON.stringify({ source: s.code, deBruijn: "off", parserRule: "Ann", rawJson: true, ivlSimplify: true }),
	});
	return res.json();
};

const summary = [];
for (const s of SNIPPETS) {
	try {
		const r = await run(s);
		fs.writeFileSync(`${OUT}/${s.id}.json`, JSON.stringify(r, null, 2));
		summary.push({ id: s.id, group: s.group, code: s.code, errors: r.errors ?? [] });
		console.log(`[${s.id}] errors=${(r.errors ?? []).length}`);
	} catch (e) {
		summary.push({ id: s.id, group: s.group, code: s.code, errors: [`DRIVER: ${String(e)}`] });
		console.log(`[${s.id}] DRIVER ERROR ${String(e)}`);
	}
}

fs.writeFileSync(`${OUT}/_summary.json`, JSON.stringify(summary, null, 2));
console.log("done");

import fs from "fs";
const OUT = "/tmp/yap-explore-results";
const ids = process.argv.slice(2);
const fields = ["source", "parsed", "elaborated", "type", "normalized", "mir", "gram", "codegenJS", "errors"];
for (const id of ids) {
	const r = JSON.parse(fs.readFileSync(`${OUT}/${id}.json`, "utf8"));
	console.log("\n\n========================================");
	console.log(`### ${id}`);
	console.log("========================================");
	for (const f of fields) {
		const v = r[f];
		if (v === undefined || v === "" || (Array.isArray(v) && v.length === 0)) {
			console.log(`\n--- ${f}: (empty) ---`);
			continue;
		}
		console.log(`\n--- ${f} ---`);
		console.log(Array.isArray(v) ? v.join("\n") : v);
	}
}

import fs from "fs";
const OUT = "/tmp/yap-explore-results";
const ids = ["identity", "struct", "tuple", "wildcard", "struct-match", "block", "row-poly", "implicit", "poly-proj"];
for (const id of ids) {
	const r = JSON.parse(fs.readFileSync(`${OUT}/${id}.json`, "utf8"));
	const js = r.codegenJS;
	if (!js) {
		console.log(`[${id}] no JS`);
		continue;
	}
	// wrap: the emitted code ends in `return main();`
	const wrapped = `(() => {\n${js}\n})()`;
	try {
		const res = eval(wrapped);
		console.log(`[${id}] => ${JSON.stringify(res)}`);
	} catch (e) {
		console.log(`[${id}] THREW: ${e instanceof Error ? e.name + ": " + e.message : String(e)}`);
	}
}

import fs from "fs";
const r = JSON.parse(fs.readFileSync("/tmp/yap-explore-results/variant-match.json", "utf8"));
// strip trailing `return main();`, expose closures
const body = r.codegenJS.replace(/return main\(\);\s*$/, "");
const driver = `
${body}
// drive: apply the 4 implicit type/row args + the real variant arg
const call = (clo, arg) => clo.__fn(clo.__env, arg);
let c = main();          // { __fn: closure_52, __env }
c = call(c, "R");        // r
c = call(c, "S");        // s
c = call(c, "A");        // A
c = call(c, "B");        // B
// c is now closure_56 wrapper; apply a variant value {__tag:"nil", payload:0}
return call(c, { __tag: "nil", payload: 0 });
`;
try {
	const res = eval(`(() => {\n${driver}\n})()`);
	console.log("variant-match(#nil 0) =>", JSON.stringify(res));
} catch (e) {
	console.log("variant-match THREW:", e instanceof Error ? e.name + ": " + e.message : String(e));
}

